// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

import {PonsRevenueVault} from "./PonsRevenueVault.sol";

/// @title PonsVaultDeployer
/// @notice Immutable helper that keeps PonsRevenueVault creation code outside the Flap factory runtime.
/// @dev The parent factory is fixed at construction and is the only allowed caller.
contract PonsVaultDeployer {
    address public immutable factory;

    constructor() {
        factory = msg.sender;
    }

    function deploy(
        address taxToken,
        address developer,
        address factoryCommissionReceiver,
        uint16 taxRateBps,
        uint16 devBps,
        uint16 holderBps
    ) external returns (address vault) {
        require(msg.sender == factory, unicode"Factory only / 仅限 PONS 工厂");
        vault = address(
            new PonsRevenueVault(taxToken, developer, factoryCommissionReceiver, taxRateBps, devBps, holderBps)
        );
    }
}

