/// @title PonsRevenueVault
/// @notice Tracker-only MVP vault: fixed-route WETH→PONS buybacks for developer and Flap Dividend holders.
/// @dev No owner, no upgrades and no arbitrary target/calldata/path setters. The only
///      privileged surface is Flap-standard Guardian emergency recovery.
contract PonsRevenueVault is VaultBaseV2, ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public immutable taxToken;
    address public immutable developer;
    address public immutable factoryCommissionReceiver;
    uint16 public immutable taxRateBps;
    uint16 public immutable devBps;
    uint16 public immutable holderBps;

    uint256 public pendingFactoryCommissionNative;
    uint256 public pendingDevNative;
    uint256 public pendingHolderNative;

    /// @notice Lazily bound once from `taxToken.dividendContract()`.
    address public dividendContract;

    event NativeSplit(address indexed from, uint256 amount, uint256 toDev, uint256 toHolder);
    event FactoryCommissionAccrued(address indexed from, uint256 amount, uint16 taxRateBps);
    event FactoryCommissionDistributed(address indexed receiver, uint256 amount);
    event DevBuyback(uint256 nativeIn, uint256 ponsReceived, uint256 ponsPaid);
    event DividendBound(address indexed dividend);
    event HolderBuyback(uint256 nativeIn, uint256 ponsReceived, uint256 ponsDeposited);
    event ForcedNativeSynced(uint256 amount, uint256 toDev, uint256 toHolder);
    event EmergencyWithdrawNative(address indexed to, uint256 amount);
    event EmergencyWithdrawToken(address indexed token, address indexed to, uint256 amount);

    modifier onlyGuardian() {
        require(msg.sender == _getGuardian(), unicode"Guardian only / 仅限 Flap Guardian");
        _;
    }

    constructor(
        address taxToken_,
        address developer_,
        address factoryCommissionReceiver_,
        uint16 taxRateBps_,
        uint16 devBps_,
        uint16 holderBps_
    ) {
        require(
            taxToken_ != address(0) && developer_ != address(0) && factoryCommissionReceiver_ != address(0),
            unicode"Zero address / 地址不能为零"
        );
        require(
            uint256(devBps_) + uint256(holderBps_) == uint256(PonsConstants.BPS_DENOMINATOR),
            unicode"Split must equal 100% / 分配比例合计必须为100%"
        );
        require(devBps_ <= PonsConstants.MAX_DEV_BPS, unicode"Developer share too high / 开发者比例过高");
        require(holderBps_ >= PonsConstants.MIN_DIVIDEND_BPS, unicode"Holder share too low / 持有人比例过低");
        require(taxRateBps_ >= 100 && taxRateBps_ <= 500, unicode"Tax rate must be 1%..5% / 税率必须为1%至5%");

        taxToken = taxToken_;
        developer = developer_;
        factoryCommissionReceiver = factoryCommissionReceiver_;
        taxRateBps = taxRateBps_;
        devBps = devBps_;
        holderBps = holderBps_;
    }

    function pons() external pure returns (address) {
        return PonsConstants.PONS;
    }

    function weth() external pure returns (address) {
        return PonsConstants.WETH;
    }

    function swapRouter() external pure returns (address) {
        return PonsConstants.SWAP_ROUTER_02;
    }

    function v3Pool() external pure returns (address) {
        return PonsConstants.V3_POOL_WETH_PONS;
    }

    /// @notice Concise dynamic configuration for legacy Flap surfaces.
    function description() public view override returns (string memory) {
        return string.concat(
            "PONS rewards: developer ",
            _formatPercent(devBps),
            "%; eligible holders ",
            _formatPercent(holderBps),
            unicode"%; holders claim through Flap Dividend / PONS 分红：开发者 ",
            _formatPercent(devBps),
            unicode"%；符合门槛的持有人 ",
            _formatPercent(holderBps),
            unicode"%；持有人通过 Flap Dividend 领取"
        );
    }

    /// @inheritdoc VaultBaseV2
    function vaultUISchema() public pure override returns (VaultUISchema memory schema) {
        schema.vaultType = unicode"PONS Rewards / PONS 分红";
        schema.description = unicode"Tax revenue buys PONS for the developer and eligible holders after the Flap factory commission / "
            unicode"税收扣除 Flap 工厂佣金后回购 PONS，分配给开发者和符合门槛的持有人";
        // Holder claims remain on Flap's native Dividend UI. Vault processing is
        // permissionless automation, so no separate end-user interaction panel is needed.
        schema.methods = new VaultMethodSchema[](0);
    }

    /// @notice Bounded native split following Flap's recommended factory commission formula.
    receive() external payable {
        uint256 amount = msg.value;
        if (amount == 0) return;
        uint16 rate = taxRateBps;

        uint256 commission = _recommendedCommission(amount, rate);
        uint256 distributable = amount - commission;
        uint256 toDev = Math.mulDiv(distributable, uint256(devBps), uint256(PonsConstants.BPS_DENOMINATOR));
        uint256 toHolder = distributable - toDev;
        pendingFactoryCommissionNative += commission;
        pendingDevNative += toDev;
        pendingHolderNative += toHolder;
        emit FactoryCommissionAccrued(msg.sender, commission, rate);
        emit NativeSplit(msg.sender, amount, toDev, toHolder);
    }

    /// @notice Permissionlessly send accrued native commission to the immutable factory developer.
    function distributeFactoryCommission() external nonReentrant returns (uint256 amount) {
        amount = pendingFactoryCommissionNative;
        require(amount != 0, unicode"No factory commission / 暂无工厂佣金");
        pendingFactoryCommissionNative = 0;
        (bool ok,) = payable(factoryCommissionReceiver).call{value: amount}("");
        require(ok, unicode"Commission transfer failed / 工厂佣金转账失败");
        emit FactoryCommissionDistributed(factoryCommissionReceiver, amount);
    }

    /// @notice Flap-standard Guardian emergency recovery for native funds.
    function emergencyWithdrawNative(
        address to
    ) external onlyGuardian nonReentrant {
        require(to != address(0), unicode"Zero address / 地址不能为零");
        uint256 bal = address(this).balance;
        pendingFactoryCommissionNative = 0;
        pendingDevNative = 0;
        pendingHolderNative = 0;
        if (bal > 0) {
            (bool ok,) = to.call{value: bal}("");
            require(ok, unicode"Native transfer failed / 原生币转账失败");
            emit EmergencyWithdrawNative(to, bal);
        }
    }

    /// @notice Flap-standard Guardian emergency recovery for stuck ERC-20 tokens.
    function emergencyWithdrawToken(
        address token,
        address to
    ) external onlyGuardian nonReentrant {
        require(token != address(0) && to != address(0), unicode"Zero address / 地址不能为零");
        uint256 bal = IERC20(token).balanceOf(address(this));
        if (bal > 0) {
            IERC20(token).safeTransfer(to, bal);
            emit EmergencyWithdrawToken(token, to, bal);
        }
    }

    /// @notice Lazy-bind `taxToken.dividendContract()` once; idempotent thereafter.
    function bindDividendContract() external returns (address dividend) {
        address existing = dividendContract;
        if (existing != address(0)) {
            return existing;
        }
        return _bindDividendFresh();
    }

    /// @notice Account forced native that arrived without `receive` (e.g. selfdestruct/coinbase).
    function syncForcedNative() external nonReentrant returns (uint256 synced) {
        uint256 accounted = pendingFactoryCommissionNative + pendingDevNative + pendingHolderNative;
        uint256 bal = address(this).balance;
        require(bal >= accounted, unicode"Balance below pending revenue / 余额低于待处理收入");

        synced = bal - accounted;
        if (synced == 0) return 0;

        uint16 rate = taxRateBps;
        uint256 commission = _recommendedCommission(synced, rate);
        uint256 distributable = synced - commission;
        uint256 toDev = Math.mulDiv(distributable, uint256(devBps), uint256(PonsConstants.BPS_DENOMINATOR));
        uint256 toHolder = distributable - toDev;
        pendingFactoryCommissionNative += commission;
        pendingDevNative += toDev;
        pendingHolderNative += toHolder;
        emit FactoryCommissionAccrued(msg.sender, commission, rate);
        emit ForcedNativeSynced(synced, toDev, toHolder);
    }

    /// @notice Internal floor from 5m TWAP quote * 97%. Uses pool.observe + TickMath/Oracle quote.
    function previewTwapMinOut(
        uint256 amountIn
    ) external view returns (uint256) {
        _assertFixedPath();
        return _twapFloor(amountIn);
    }

    /// @notice Permissionlessly buy PONS with accrued holder native and deposit it into Flap Dividend.
    function processHolderBuybackAndDeposit(
        uint256 nativeAmountIn,
        uint256 callerMinPonsOut,
        uint256 deadline
    ) external nonReentrant returns (uint256 ponsReceived, uint256 ponsDeposited) {
        (ponsReceived,, ponsDeposited) = _processBuybacks(0, nativeAmountIn, callerMinPonsOut, deadline);
    }

    /// @notice Permissionlessly process developer and holder pending native through one fixed-route swap.
    /// @dev PONS output is allocated pro rata to native consumed; rounding remainder belongs to holders.
    function processBuybacks(
        uint256 devNativeAmountIn,
        uint256 holderNativeAmountIn,
        uint256 callerMinPonsOut,
        uint256 deadline
    ) external nonReentrant returns (uint256 ponsReceived, uint256 devPonsPaid, uint256 holderPonsDeposited) {
        return _processBuybacks(devNativeAmountIn, holderNativeAmountIn, callerMinPonsOut, deadline);
    }

    function _processBuybacks(
        uint256 devNativeAmountIn,
        uint256 holderNativeAmountIn,
        uint256 callerMinPonsOut,
        uint256 deadline
    ) internal returns (uint256 ponsReceived, uint256 devPonsPaid, uint256 holderPonsDeposited) {
        // A caller-supplied expiry is the intended protection for Router02, whose
        // exactInputSingle struct has no deadline field.
        // forge-lint: disable-next-line(block-timestamp)
        require(block.timestamp <= deadline, unicode"Deadline expired / 截止时间已过");
        require(
            devNativeAmountIn != 0 || holderNativeAmountIn != 0,
            unicode"Amount must be greater than zero / 数量必须大于零"
        );
        require(
            devNativeAmountIn <= pendingDevNative,
            unicode"Exceeds pending developer revenue / 超过待处理开发者收入"
        );
        require(
            holderNativeAmountIn <= pendingHolderNative,
            unicode"Exceeds pending holder revenue / 超过待处理持有人收入"
        );

        uint256 nativeAmountIn = devNativeAmountIn + holderNativeAmountIn;

        _assertFixedPath();
        address dividend;
        if (holderNativeAmountIn != 0) {
            dividend = _requireLiveDividend(); // also enforces totalShares > 0
        }

        uint256 internalFloor = _twapFloor(nativeAmountIn);
        uint256 effectiveMin = callerMinPonsOut > internalFloor ? callerMinPonsOut : internalFloor;

        // Effects before interactions
        pendingDevNative -= devNativeAmountIn;
        pendingHolderNative -= holderNativeAmountIn;

        ponsReceived = _swapNativeForPons(nativeAmountIn, effectiveMin);

        devPonsPaid = Math.mulDiv(ponsReceived, devNativeAmountIn, nativeAmountIn);
        holderPonsDeposited = ponsReceived - devPonsPaid;
        require(
            (devNativeAmountIn == 0 || devPonsPaid != 0) && (holderNativeAmountIn == 0 || holderPonsDeposited != 0),
            unicode"PONS allocation is zero / PONS 分配为零"
        );

        IERC20 ponsToken = IERC20(PonsConstants.PONS);
        if (devNativeAmountIn != 0) {
            ponsToken.safeTransfer(developer, devPonsPaid);
            emit DevBuyback(devNativeAmountIn, devPonsPaid, devPonsPaid);
        }

        if (holderNativeAmountIn != 0) {
            _depositPons(dividend, ponsToken, holderPonsDeposited);
            emit HolderBuyback(holderNativeAmountIn, holderPonsDeposited, holderPonsDeposited);
        }
    }

    // ─── internal ───────────────────────────────────────────────────────────

    function _recommendedCommission(
        uint256 amount,
        uint16 rate
    ) internal pure returns (uint256) {
        if (rate <= 100) {
            return Math.mulDiv(amount, 600, PonsConstants.BPS_DENOMINATOR);
        }
        return Math.mulDiv(amount, 6, rate);
    }

    function _swapNativeForPons(
        uint256 nativeAmountIn,
        uint256 effectiveMin
    ) internal returns (uint256 ponsReceived) {
        IWETH9(PonsConstants.WETH).deposit{value: nativeAmountIn}();

        IERC20 wethToken = IERC20(PonsConstants.WETH);
        wethToken.forceApprove(PonsConstants.SWAP_ROUTER_02, nativeAmountIn);

        uint256 ponsBefore = IERC20(PonsConstants.PONS).balanceOf(address(this));
        ISwapRouter02(PonsConstants.SWAP_ROUTER_02)
            .exactInputSingle(
                ISwapRouter02.ExactInputSingleParams({
                tokenIn: PonsConstants.WETH,
                tokenOut: PonsConstants.PONS,
                fee: PonsConstants.V3_FEE,
                recipient: address(this),
                amountIn: nativeAmountIn,
                amountOutMinimum: effectiveMin,
                sqrtPriceLimitX96: 0
            })
            );
        ponsReceived = IERC20(PonsConstants.PONS).balanceOf(address(this)) - ponsBefore;
        require(
            ponsReceived != 0 && ponsReceived >= effectiveMin, unicode"Insufficient PONS output / PONS 输出不足"
        );

        wethToken.forceApprove(PonsConstants.SWAP_ROUTER_02, 0);
    }

    function _depositPons(
        address dividend,
        IERC20 ponsToken,
        uint256 amount
    ) internal {
        ponsToken.forceApprove(dividend, amount);

        uint256 divPonsBefore = ponsToken.balanceOf(dividend);
        bool ok = IFlapDividendBinding(dividend).deposit(amount);
        require(ok, unicode"Dividend deposit failed / 分红存入失败");
        uint256 deposited = ponsToken.balanceOf(dividend) - divPonsBefore;
        require(deposited == amount, unicode"Dividend deposit amount mismatch / 分红存入数量不一致");

        ponsToken.forceApprove(dividend, 0);
    }

    function _bindDividendFresh() internal returns (address dividend) {
        dividend = IFlapTaxTokenDividend(taxToken).dividendContract();
        require(
            dividend != address(0) && dividend.code.length != 0,
            unicode"Dividend contract not ready / 分红合约尚未就绪"
        );

        IFlapDividendBinding view_ = IFlapDividendBinding(dividend);
        require(view_.taxToken() == taxToken, unicode"Dividend tax token mismatch / 分红税收代币不匹配");
        require(
            view_.dividendToken() == PonsConstants.PONS,
            unicode"Dividend token must be PONS / 分红代币必须为 PONS"
        );

        dividendContract = dividend;
        emit DividendBound(dividend);
    }

    function _requireLiveDividend() internal returns (address dividend) {
        dividend = dividendContract;
        if (dividend == address(0)) {
            dividend = _bindDividendFresh();
        }

        address live = IFlapTaxTokenDividend(taxToken).dividendContract();
        require(live == dividend, unicode"Dividend contract changed / 分红合约已变化");

        IFlapDividendBinding view_ = IFlapDividendBinding(dividend);
        require(view_.taxToken() == taxToken, unicode"Dividend tax token mismatch / 分红税收代币不匹配");
        require(
            view_.dividendToken() == PonsConstants.PONS,
            unicode"Dividend token must be PONS / 分红代币必须为 PONS"
        );
        require(view_.totalShares() != 0, unicode"No eligible dividend shares / 暂无符合条件的分红份额");
    }

    function _assertFixedPath() internal view {
        IUniswapV3PoolMinimal pool = IUniswapV3PoolMinimal(PonsConstants.V3_POOL_WETH_PONS);
        ISwapRouter02 router = ISwapRouter02(PonsConstants.SWAP_ROUTER_02);

        require(pool.token0() == PonsConstants.WETH, unicode"Invalid WETH/PONS path / WETH-PONS 路径无效");
        require(pool.token1() == PonsConstants.PONS, unicode"Invalid WETH/PONS path / WETH-PONS 路径无效");
        require(pool.fee() == PonsConstants.V3_FEE, unicode"Invalid pool fee / 流动池费率无效");
        require(router.WETH9() == PonsConstants.WETH, unicode"Invalid router WETH / 路由 WETH 无效");
        require(
            pool.factory() == router.factory(),
            unicode"Router and pool factory mismatch / 路由与流动池工厂不匹配"
        );
    }

    function _twapFloor(
        uint256 amountIn
    ) internal view returns (uint256) {
        if (amountIn == 0) return 0;
        require(amountIn <= type(uint128).max, unicode"Amount too large / 数量过大");

        (int24 shortTwap,) = _observeTwaps();
        // `amountIn` was bounded to uint128 immediately above.
        // forge-lint: disable-next-line(unsafe-typecast)
        uint128 boundedAmountIn = uint128(amountIn);
        uint256 quote = V3OracleQuote.getQuoteAtTick(shortTwap, boundedAmountIn, PonsConstants.WETH, PonsConstants.PONS);
        return Math.mulDiv(quote, uint256(PonsConstants.TWAP_FLOOR_BPS), uint256(PonsConstants.BPS_DENOMINATOR));
    }

    function _observeTwaps() internal view returns (int24 shortTwap, int24 longTwap) {
        IUniswapV3PoolMinimal pool = IUniswapV3PoolMinimal(PonsConstants.V3_POOL_WETH_PONS);

        uint32[] memory secondsAgos = new uint32[](3);
        secondsAgos[0] = PonsConstants.TWAP_LONG_SECONDS;
        secondsAgos[1] = PonsConstants.TWAP_SHORT_SECONDS;
        secondsAgos[2] = 0;

        (int56[] memory tickCumulatives,) = pool.observe(secondsAgos);

        shortTwap = V3OracleQuote.consultTick(tickCumulatives[1], tickCumulatives[2], PonsConstants.TWAP_SHORT_SECONDS);
        longTwap = V3OracleQuote.consultTick(tickCumulatives[0], tickCumulatives[2], PonsConstants.TWAP_LONG_SECONDS);

        (, int24 spotTick,,,,,) = pool.slot0();

        require(
            _tickAbsDiff(spotTick, shortTwap) <= uint256(int256(PonsConstants.MAX_SPOT_SHORT_TICK_DELTA)),
            unicode"Spot price deviates from short TWAP / 现价偏离短期 TWAP"
        );
        require(
            _tickAbsDiff(shortTwap, longTwap) <= uint256(int256(PonsConstants.MAX_SHORT_LONG_TICK_DELTA)),
            unicode"Short TWAP deviates from long TWAP / 短期 TWAP 偏离长期 TWAP"
        );
    }

    function _tickAbsDiff(
        int24 a,
        int24 b
    ) private pure returns (uint256) {
        // The selected branch is non-negative and int24 differences fit in int256.
        // forge-lint: disable-next-line(unsafe-typecast)
        return a >= b ? uint256(int256(a) - int256(b)) : uint256(int256(b) - int256(a));
    }

    function _formatPercent(
        uint16 bps
    ) private pure returns (string memory) {
        uint256 whole = uint256(bps) / 100;
        uint256 remainder = uint256(bps) % 100;
        if (remainder == 0) return Strings.toString(whole);
        if (remainder % 10 == 0) {
            return string.concat(Strings.toString(whole), ".", Strings.toString(remainder / 10));
        }
        return string.concat(Strings.toString(whole), remainder < 10 ? ".0" : ".", Strings.toString(remainder));
    }
}

