    /// @notice TWAP tick from cumulative delta, rounding toward negative infinity.
    function consultTick(
        int56 tickCumulativeStart,
        int56 tickCumulativeEnd,
        uint32 secondsAgo
    ) internal pure returns (int24 arithmeticMeanTick) {
        int56 tickCumulativesDelta = tickCumulativeEnd - tickCumulativeStart;
        // Callers use canonical V3 pool cumulatives over a non-zero fixed window;
        // the resulting mean is therefore within Uniswap's int24 tick bounds.
        // forge-lint: disable-next-line(unsafe-typecast)
        arithmeticMeanTick = int24(tickCumulativesDelta / int56(uint56(secondsAgo)));
        // Always round to negative infinity (Uniswap OracleLibrary.consult)
        if (tickCumulativesDelta < 0 && (tickCumulativesDelta % int56(uint56(secondsAgo)) != 0)) {
            arithmeticMeanTick--;
        }
    }
}
